2	/**
3	 * ADR-0008: rebuild the whole chunk layer from `articles` and `live_posts`.
4	 *
5	 * Wipes `chunks` and rebuilds every article's span or live-post chunks inside
6	 * one transaction (ArticleDb.rebuildAllChunks), then optimizes the FTS5
7	 * index. Safe to run any time, and safe to re-run repeatedly, because chunk
8	 * refs are deterministic (ADR-0004): a rebuild reproduces the exact same
9	 * chunk_ref set byte-for-byte, it never mints new identities.
10	 *
11	 * Usage: npx tsx scripts/rebuild-chunks.ts [outputDir]
12	 */
13	
14	import { OUTPUT_DIR } from '../src/cli/config.js';
15	import { ArticleDb } from '../src/db.js';
16	
17	export function rebuildChunks(outputDir: string): { articlesProcessed: number; chunksBuilt: number; liveUpdateArticles: number; durationMs: number } {
18	  const db = new ArticleDb(outputDir);
19	  try {
20	    const startedAt = Date.now();
21	    const stats = db.rebuildAllChunks();
22	    return { ...stats, durationMs: Date.now() - startedAt };
23	  } finally {
24	    db.close();
25	  }
26	}
27	
28	function main(): void {
29	  const outputDir = process.argv[2] ?? OUTPUT_DIR;
30	  const stats = rebuildChunks(outputDir);
31	  console.log(
32	    `rebuild-chunks: ${stats.articlesProcessed} article(s) processed ` +
33	    `(${stats.liveUpdateArticles} live-update), ${stats.chunksBuilt} chunk(s) built ` +
34	    `in ${(stats.durationMs / 1000).toFixed(1)}s`,
35	  );
36	}
