/**
 * ADR-0006: backfill 64-bit simhashes for every Article missing one.
 *
 * Idempotent, same pattern as scripts/backfill-refs.ts: only touches rows
 * WHERE simhash IS NULL, so a re-run over an already-backfilled store
 * computes zero new hashes. Scoped to type = 'article' by
 * ArticleDb.getArticlesMissingSimhash (Live updates are continuously
 * mutating blogs, not syndicated stories; near-duplicate detection does not
 * apply to them, see implementation-notes.md's T9 entry).
 *
 * Accepts an already-open ArticleDb (the shape scan-runner.ts's end-of-scan
 * hook needs, mirroring src/repair.ts's drainRepairQueue) as well as a bare
 * outputDir when run standalone.
 *
 * Usage: npx tsx scripts/backfill-simhash.ts [outputDir]
 */

import { OUTPUT_DIR } from '../src/cli/config.js';
import { ArticleDb } from '../src/db.js';
import { computeSimhash } from '../src/dedup/simhash.js';

export function backfillSimhash(db: ArticleDb): number {
  const rows = db.getArticlesMissingSimhash();
  const tx = db.raw().transaction((items: typeof rows) => {
    for (const row of items) db.updateSimhash(row.id, computeSimhash(row.body));
  });
  tx(rows);
  return rows.length;
}

export function backfillSimhashForOutputDir(outputDir: string): number {
  const db = new ArticleDb(outputDir);
  try {
    return backfillSimhash(db);
  } finally {
    db.close();
  }
}

function main(): void {
  const outputDir = process.argv[2] ?? OUTPUT_DIR;
  const count = backfillSimhashForOutputDir(outputDir);
  console.log(`backfill-simhash: computed ${count} simhash value(s) in ${outputDir}`);
}

